export function checkedOutfitReferencePath(value){
 if(typeof value!=='string'||!/^\/assets\/(?:[A-Za-z0-9_-]+\/)*[A-Za-z0-9_-]+\.(?:png|webp)$/.test(value))throw Error('ข้อมูลชุดอ้างอิงไม่ถูกต้อง');
 return value;
}

export function parsePortraitIdentityBox(value){
 if(value===undefined||value===null||value==='')return null;
 let box;try{box=typeof value==='string'?JSON.parse(value):value}catch{throw Error('ข้อมูลกรอบใบหน้าต้นฉบับไม่ถูกต้อง กรุณาลองใหม่')}
 if(!Array.isArray(box)||box.length!==4||box.some(n=>typeof n!=='number'||!Number.isFinite(n)||n<0||n>1)||box[0]>=box[2]||box[1]>=box[3])throw Error('ข้อมูลกรอบใบหน้าต้นฉบับไม่ถูกต้อง กรุณาลองใหม่');
 return [...box];
}
export async function portraitIdentityCrop(input,box){
 if(!box)return null;
 // Browser landmarks use the display orientation, including EXIF rotation.
 const metadata=await sharp(input.buffer).metadata(),{width,height}=metadata.autoOrient||metadata;
 if(!width||!height)throw Error('อ่านภาพต้นฉบับสำหรับยืนยันใบหน้าไม่ได้');
 const left=Math.floor(box[0]*width),top=Math.floor(box[1]*height),right=Math.ceil(box[2]*width),bottom=Math.ceil(box[3]*height);
 if(right-left<16||bottom-top<16)throw Error('ใบหน้าในภาพต้นฉบับเล็กเกินไป กรุณาใช้ภาพที่เห็นใบหน้าชัดเจน');
 // The close-up is derived only from this request's uploaded image. It is an
 // additional view of the same person, never a previous output or reference.
 // Bound only the conditioning view. The original input and generated master
 // retain their existing dimensions, and small faces are never enlarged.
 return sharp(input.buffer).rotate().extract({left,top,width:right-left,height:bottom-top}).resize({width:1024,height:1024,fit:'inside',withoutEnlargement:true}).png().toBuffer();
}

export function parseFemaleMakeupReference(fields,selected){
 const value=fields.femaleMakeupReference;
 if(value===undefined)return null;
 if((selected?.gender||fields.portraitMode)!=='female'||fields.portraitMode!=='female'||fields.femaleEyeStyle!=='makeup'||fields.creditKind!=='hairstyle')throw Error('รูปอ้างอิงการแต่งหน้าใช้ได้เฉพาะการเปลี่ยนทรงผมหญิงที่เลือกแต่งหน้า');
 if(typeof value!=='string'||value.length>512*1024||!value.startsWith('data:image/jpeg;base64,'))throw Error('ข้อมูลรูปอ้างอิงการแต่งหน้าไม่ถูกต้อง กรุณาลองใหม่');
 const encoded=value.slice('data:image/jpeg;base64,'.length);
 if(!encoded.length||encoded.length%4||!/^[A-Za-z0-9+/]+={0,2}$/.test(encoded))throw Error('ข้อมูลรูปอ้างอิงการแต่งหน้าไม่ถูกต้อง กรุณาลองใหม่');
 const image=Buffer.from(encoded,'base64');
 if(image.length<4||image[0]!==255||image[1]!==216||image[2]!==255||image.toString('base64')!==encoded)throw Error('ข้อมูลรูปอ้างอิงการแต่งหน้าไม่ถูกต้อง กรุณาลองใหม่');
 return image;
}
export async function checkedFemaleMakeupReference(image){
 if(!image)return null;
 try{
  const metadata=await sharp(image).metadata();
  if(metadata.format!=='jpeg'||!metadata.width||!metadata.height||metadata.width<16||metadata.height<16||metadata.width>512||metadata.height>512||(metadata.pages||1)>1)throw Error('invalid makeup reference dimensions');
  await sharp(image).raw().toBuffer();
  return image;
 }catch{throw Error('อ่านรูปอ้างอิงการแต่งหน้าไม่ได้ กรุณาลองใหม่')}
}

export function validateProductionPortrait(input,fields={}){
 validateEnglishStudioFinish(fields);
 if(fields.englishHairFit!==undefined){if(!usesEnglishStudioFinish(fields)&&!isEnglishHeadPortrait(fields))throw Error('Invalid English hair placement option');parseEnglishHairFit(fields.englishHairFit)}
 validateCurrentHairRequest(fields);
 if(!input?.buffer?.length||!['image/png','image/jpeg','image/webp'].includes(input.mimetype))throw Error('กรุณาใช้ภาพ PNG, JPG หรือ WEBP');
 if(fields.mode||fields.hairRootTarget||fields.maleHairReplacement)throw Error('กรุณารีเฟรชหน้าเว็บเพื่อใช้ขั้นตอนประมวลผลล่าสุด');
 if(fields.hairReferenceVersion&&fields.hairReferenceVersion!==HAIR_REFERENCE_VERSION)throw Error('ข้อมูลทรงผมไม่ตรงกับชุดล่าสุด กรุณารีเฟรชหน้าเว็บ');
 const id=fields.hairId||'original',selected=productionHair(id);
 if(fields.femaleFinishPair&&(!isAiMakeupPairVersion(fields.femaleFinishPair)||(selected?.gender||fields.portraitMode)!=='female'||fields.femaleEyeStyle!=='natural'||!isOriginalPortraitAiRequest(fields)))throw Error('ตัวเลือกภาพแต่งหน้าคู่ไม่ถูกต้อง กรุณารีเฟรชหน้าเว็บ');
 if(fields.hairReferenceVersion&&!id.startsWith('seedream-'))throw Error('ภาพอ้างอิงนี้ใช้ได้เฉพาะทรงผมในแค็ตตาล็อก');
 if(id!=='original'&&!selected)throw Error('ทรงผมเดิมถูกนำออกแล้ว กรุณาเลือกทรงจากชุดล่าสุด');
 if(!selected&&!['female','male'].includes(fields.portraitMode))throw Error('กรุณาเลือกหญิงหรือชายก่อนประมวลผล');
 if(['korean-rosy-v1','soft-rosy-v1'].includes(fields.femaleEyeStyle)&&fields.outfitReferencePath)checkedOutfitReferencePath(fields.outfitReferencePath);
 if(fields.portraitComposition){
  if((!isEnglishBodyPortrait(fields)&&!(isEnglishHeadPortrait(fields)&&fields.englishStudioFinishVersion===ENGLISH_HEAD_FINISH_VERSION))||!isEnglishBodyOutfitPath(fields.neckOutfitReferencePath))throw Error('Invalid English outfit portrait option');
 }
 if(fields.neckOutfitReferencePath)checkedOutfitReferencePath(fields.neckOutfitReferencePath);
 parsePortraitIdentityBox(fields.faceIdentityBox);
 parseFemaleMakeupReference(fields,selected);
 parseStudioSkinRequest(fields,selected?.gender||fields.portraitMode);
 return selected;
}
